+import type * as d3 from 'd3';
+
+type ChildAccessor<T> = (datum: T) => Iterable<T> | null | undefined;
+
+type MutableHierarchyNode<T> = {
+  data: T;
+  children?: MutableHierarchyNode<T>[];
+  parent: MutableHierarchyNode<T> | null;
+  depth: number;
+  height: number;
+  value?: number;
+  x0: number;
+  y0: number;
+  x1: number;
+  y1: number;
+  sort(
+    compare: (a: d3.HierarchyNode<T>, b: d3.HierarchyNode<T>) => number
+  ): MutableHierarchyNode<T>;
+  sum(value: (datum: T) => number): MutableHierarchyNode<T>;
+};
+
+type CompatTreemapLayout<T> = {
+  (root: d3.HierarchyNode<T>): d3.HierarchyRectangularNode<T>;
+  size(size: [number, number]): CompatTreemapLayout<T>;
+  round(round: boolean): CompatTreemapLayout<T>;
+  paddingInner(padding: number): CompatTreemapLayout<T>;
+};
+
+export function hierarchy<T>(
+  data: T,
+  childrenAccessor: ChildAccessor<T>
+): d3.HierarchyNode<T> {
+  function build(
+    datum: T,
+    parent: MutableHierarchyNode<T> | null,
+    depth: number
+  ): MutableHierarchyNode<T> {
+    const node = {
+      data: datum,
+      parent,
+      depth,
+      height: 0,
+      value: undefined,
+      x0: 0,
+      y0: 0,
+      x1: 0,
+      y1: 0,
+      sort(compare) {
+        sortNode(this, compare);
+        return this;
+      },
+      sum(value) {
+        sumNode(this, value);
+        return this;
+      }
+    } as MutableHierarchyNode<T>;
+
+    const childData = childrenAccessor(datum);
+    const children = childData ? Array.from(childData) : [];
+    if (children.length) {
+      node.children = children.map((child) => build(child, node, depth + 1));
+      node.height = 1 + Math.max(...node.children.map((child) => child.height));
+    }
+
+    return node;
+  }
+
+  return build(data, null, 0) as unknown as d3.HierarchyNode<T>;
+}
+
+export function scaleLinear(): d3.ScaleLinear<number, number> {
+  let currentDomain: [number, number] = [0, 1];
+  let currentRange: [number, number] = [0, 1];
+
+  const scale = ((value: number) => {
+    const domainSpan = currentDomain[1] - currentDomain[0];
+    const t = domainSpan === 0 ? 0 : (value - currentDomain[0]) / domainSpan;
+    return currentRange[0] + t * (currentRange[1] - currentRange[0]);
+  }) as unknown as d3.ScaleLinear<number, number>;
+
+  scale.domain = ((domain?: Iterable<number>) => {
+    if (domain === undefined) {
+      return [...currentDomain];
+    }
+    const next = Array.from(domain);
+    currentDomain = [next[0], next[1]];
+    return scale;
+  }) as d3.ScaleLinear<number, number>['domain'];
+
+  scale.range = ((range?: Iterable<number>) => {
+    if (range === undefined) {
+      return [...currentRange];
+    }
+    const next = Array.from(range);
+    currentRange = [next[0], next[1]];
+    return scale;
+  }) as d3.ScaleLinear<number, number>['range'];
+
+  scale.invert = ((value: number) => {
+    const rangeSpan = currentRange[1] - currentRange[0];
+    const t = rangeSpan === 0 ? 0 : (value - currentRange[0]) / rangeSpan;
+    return currentDomain[0] + t * (currentDomain[1] - currentDomain[0]);
+  }) as d3.ScaleLinear<number, number>['invert'];
+
+  scale.copy = (() => {
+    return scaleLinear().domain(currentDomain).range(currentRange);
+  }) as d3.ScaleLinear<number, number>['copy'];
+
+  return scale;
+}
+
+export function treemap<T>(): CompatTreemapLayout<T> {
+  let layoutSize: [number, number] = [1, 1];
+  let shouldRound = false;
+  let innerPadding = 0;
+
+  const layout = ((root: d3.HierarchyNode<T>) => {
+    const rectangularRoot = root as unknown as MutableHierarchyNode<T>;
+    rectangularRoot.x0 = 0;
+    rectangularRoot.y0 = 0;
+    rectangularRoot.x1 = layoutSize[0];
+    rectangularRoot.y1 = layoutSize[1];
+    layoutChildren(rectangularRoot);
+    return rectangularRoot as unknown as d3.HierarchyRectangularNode<T>;
+  }) as CompatTreemapLayout<T>;
